#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define main candidate_main
#include "block-0.txt"
#undef main

static int hexval(int c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static void put_hex(const char *s, size_t n)
{
    size_t i;
    for (i = 0; i < n; i++) printf("%02x", (unsigned char)s[i]);
}

static int fail_out(const char *msg)
{
    printf("err ");
    put_hex(msg, strlen(msg));
    putchar(10);
    return 0;
}

int main(int argc, char **argv)
{
    size_t len, n, i, count = 0, cap = 64;
    char *buf;
    char **toks;
    int index = 0;

    if (argc != 2) return fail_out("bad driver arguments");
    len = strlen(argv[1]);
    if (len % 2) return fail_out("odd hex length");
    n = len / 2;
    buf = malloc(n + 1);
    if (!buf) return fail_out("out of memory");
    for (i = 0; i < n; i++) {
        int hi = hexval(argv[1][2 * i]);
        int lo = hexval(argv[1][2 * i + 1]);
        if (hi < 0 || lo < 0) return fail_out("bad hex input");
        buf[i] = (char)(hi * 16 + lo);
    }
    buf[n] = 0;
    toks = malloc(cap * sizeof(char *));
    if (!toks) return fail_out("out of memory");
    for (;;) {
        int before = index;
        char *t = next_token(buf, &index);
        if (t == NULL) break;
        if (index == before) {
            free(t);
            return fail_out("non-advancing lexer: index unchanged on non-NULL token");
        }
        if (count == cap) {
            cap *= 2;
            toks = realloc(toks, cap * sizeof(char *));
            if (!toks) return fail_out("out of memory");
        }
        toks[count++] = t;
        if (count > 100000) return fail_out("too many tokens: possible non-terminating lexer");
    }
    printf("ok");
    for (i = 0; i < count; i++) {
        putchar(32);
        put_hex(toks[i], strlen(toks[i]));
        free(toks[i]);
    }
    putchar(10);
    free(toks);
    free(buf);
    return 0;
}

