import json
import subprocess
import sys


def emit(obj):
    sys.stdout.write(json.dumps(obj) + chr(10))


def get_text(case):
    inp = case.get('input') if isinstance(case, dict) else None
    if isinstance(inp, dict):
        return inp.get('text')
    return inp


def main():
    try:
        with open('inputs.json', 'r', encoding='utf-8') as f:
            cases = json.load(f)
    except Exception as e:
        emit({'results': [], 'harness_error': 'cannot read inputs.json: ' + str(e)})
        return
    if not isinstance(cases, list):
        emit({'results': [], 'harness_error': 'inputs.json is not a list'})
        return
    compile_error = None
    try:
        cp = subprocess.run(['cc', '-o', 'driver', 'driver.c'], capture_output=True, encoding='utf-8', errors='replace', timeout=5)
        if cp.returncode != 0:
            compile_error = (cp.stderr or cp.stdout)[-1500:]
    except Exception as e:
        emit({'results': [], 'harness_error': 'compiler invocation failed: ' + str(e)})
        return
    results = []
    for case in cases:
        cid = case.get('id') if isinstance(case, dict) else None
        if compile_error is not None:
            results.append({'id': cid, 'error': 'candidate failed to compile: ' + compile_error})
            continue
        text = get_text(case)
        if not isinstance(text, str) or chr(0) in text:
            results.append({'id': cid, 'error': 'input text missing, not a string, or contains NUL'})
            continue
        arg = text.encode('utf-8').hex()
        try:
            rp = subprocess.run(['./driver', arg], capture_output=True, encoding='utf-8', errors='replace', timeout=5)
        except subprocess.TimeoutExpired:
            results.append({'id': cid, 'error': 'candidate timeout after 5 seconds'})
            continue
        except Exception as e:
            results.append({'id': cid, 'error': 'driver execution failed: ' + str(e)})
            continue
        if rp.returncode != 0:
            results.append({'id': cid, 'error': 'candidate process exited with code ' + str(rp.returncode)})
            continue
        first = rp.stdout.split(chr(10))[0]
        parts = first.split(' ')
        try:
            if parts[0] == 'ok':
                toks = [bytes.fromhex(h).decode('utf-8', 'replace') for h in parts[1:]]
                results.append({'id': cid, 'actual': toks})
            elif parts[0] == 'err':
                msg = bytes.fromhex(parts[1]).decode('utf-8', 'replace') if len(parts) > 1 else ''
                results.append({'id': cid, 'error': msg})
            else:
                results.append({'id': cid, 'error': 'unexpected driver output'})
        except Exception as e:
            results.append({'id': cid, 'error': 'could not decode driver output: ' + str(e)})
    emit({'results': results})


if __name__ == '__main__':
    main()
